  1	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
  2	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
  3	// Super on Linux. See orca.nix.
  4	//
  5	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
  6	//
  7	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
  8	// facade its comment promises) for the definitions, normalisation and the
  9	// conflict check, so a version bump regenerates the table instead of
 10	// silently drifting from it.
 11	const fs = require('fs');
 12	const path = require('path');
 13	
 14	const [shared, chordsFile] = process.argv.slice(2);
 15	const kb = require(path.resolve(shared, 'keybindings.js'));
 16	
 17	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
 18	// "Cmd+Shift+W", Hyprland's modifier and keysym aliases included (keysyms
 19	// case-insensitively, as Hyprland reads them). Mouse, switch and media binds,
 20	// and the few keys Orca has no chord for (NO_CHORD), are skipped. Anything
 21	// else that does not translate fails the build: an unknown name may be an
 22	// Orca chord spelled another way, and guessing "harmless" ships a dead key.
 23	const MODS = {
 24	  SUPER: 'Cmd', WIN: 'Cmd', LOGO: 'Cmd', MOD4: 'Cmd',
 25	  CTRL: 'Ctrl', CONTROL: 'Ctrl',
 26	  ALT: 'Alt', MOD1: 'Alt',
 27	  SHIFT: 'Shift',
 28	};
 29	const KEYS = {
 30	  return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown',
 31	  grave: 'Backquote', apostrophe: 'Quote',
 32	  prior: 'PageUp', next: 'PageDown', page_up: 'PageUp', page_down: 'PageDown',
 33	  kp_add: 'NumpadAdd', kp_subtract: 'NumpadSubtract',
 34	};
 35	const NO_CHORD = new Set(['print', 'scroll_lock', 'pause', 'sys_req', 'menu']);
 36	const taken = new Set();
 37	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
 38	  const parts = chord.split('+').map((s) => s.trim());
 39	  const key = parts.pop();
 40	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
 41	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
 42	  if (!mods.every(Boolean)) throw new Error(`unknown modifier in Hyprland bind "${chord}"`);
 43	  // Bare keys too: Orca's few bare chords (F7, Delete) can be Hyprland's.
 44	  if (NO_CHORD.has(key.toLowerCase())) continue;
 45	  const n = kb.normalizeKeybindingWithOptions([...mods, KEYS[key.toLowerCase()] ?? key].join('+'), {
 46	    allowBareKeybindings: true,
 47	    allowShiftOnlyKeybindings: true,
 48	  });
 49	  if (!n.ok) {
 50	    throw new Error(`cannot translate Hyprland bind "${chord}" (${n.error}); map its key in KEYS, or NO_CHORD if Orca has none`);
 51	  }
 52	  taken.add(n.value);
 53	}
 54	// A digit-index action's one binding stands for its whole 1-9 family.
 55	const isTaken = (id, binding) =>
 56	  kb.isDigitIndexActionId(id)
 57	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
 58	    : taken.has(binding);
 59	
 60	const overrides = {};
 61	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
 62	const fellBack = new Set();
 63	for (const def of kb.KEYBINDING_DEFINITIONS) {
 64	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
 65	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
 66	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
 67	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
 68	    return n.value;
 69	  });
 70	  const free = mac.filter((b) => !isTaken(def.id, b));
 71	  if (free.length < mac.length) {
 72	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
 73	  }
 74	  // Every chord taken: leave the action on its Linux default rather than
 75	  // unbinding it. No macOS binding at all is different -- unbound there, so
 76	  // unbound here ([]). Same as the Linux default: nothing to say.
 77	  if (mac.length > 0 && free.length === 0) {
 78	    fellBack.add(def.id);
 79	    continue;
 80	  }
 81	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
 82	  overrides[def.id] = free;
 83	}
 84	
 85	// A fallback can land on a generated chord the Mac table never had to keep
 86	// apart from it. Orca dispatches some actions across scopes, ahead of the
 87	// conflict check's scope groups -- the workspace digits before the tab
 88	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
 89	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
 90	// Such an action goes back to its own Linux default too, until none is left.
 91	const identities = (id, bindings) =>
 92	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
 93	for (;;) {
 94	  const held = new Set(
 95	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
 96	  );
 97	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
 98	  if (shadowed.length === 0) break;
 99	  for (const id of shadowed) {
100	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
101	    delete overrides[id];
102	    fellBack.add(id);
103	  }
104	}
105	
106	// Orca drops every action in a conflicting set at load, with only a line in
107	// its diagnostics; fail the build instead.
108	const conflicts = kb.findKeybindingConflicts('linux', overrides);
109	if (conflicts.length > 0) {
110	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
111	}
112	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);

