 76	try {
 77	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
 78	  if (!isObject(s?.linux)) throw new Error('no .linux object');
 79	  prev = s.linux;
 80	} catch (e) {
 81	  // No sidecar is a first run. A bad one stops the merge: it decides what
 82	  // may be overwritten, and reading it as empty overwrites every key the UI
 83	  // has changed.
 84	  if (e.code !== 'ENOENT') {
 85	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
 86	    process.exit(0);
 87	  }
 88	}
 89	
 90	const platforms = isObject(doc.platforms) ? doc.platforms : {};
 91	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
 92	// The UI's: a value on a claimed key that differs from its claim, or any
 93	// value on a key never claimed. Absent (reset in the UI) is not a change --
 94	// the reset target is this table, so it comes back.
 95	const theirs = new Set(
 96	  [...new Set([...Object.keys(prev), ...Object.keys(owned)])].filter(
 97	    (id) => id in linux && (id in prev ? !same(linux[id], prev[id]) : true),
 98	  ),
 99	);
100	for (const id of Object.keys(prev)) {
101	  if (!theirs.has(id)) delete linux[id];
102	}
103	// Every owned key still in the file is the UI's by now (stale ones are
104	// gone), so writing the rest overwrites nothing.
105	const written = {};
106	for (const [id, bindings] of Object.entries(owned)) {
107	  if (theirs.has(id)) continue;
108	  linux[id] = bindings;
109	  written[id] = bindings;
110	}
111	
112	// What Orca's loader feeds its conflict pass: common, then the platform
113	// section over it, with its string shorthand and null/false expanded.
114	// Common is the root's action keys in the legacy shape with no .keybindings.
115	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
116	// Orca's loader (jHn): null/false unbind; a string is a comma list; an array
117	// of strings may hold comma lists too; one bad chord rejects the whole value,
118	// leaving the action on its default (undefined here). Both normalisers return
119	// string[] or {ok:false}.
120	const expand = (id, v) => {
121	  if (v === null || v === false) return [];
122	  const n =
123	    typeof v === 'string' ? kb.normalizeKeybindingListForAction(id, v)
124	      : Array.isArray(v) && v.every((b) => typeof b === 'string') ? kb.normalizeKeybindingArrayForAction(id, v)
125	        : null;
126	  return Array.isArray(n) ? n : undefined;
127	};
128	// Each section parsed on its own, then layered (q$): a bad platform value is
129	// dropped, not allowed to hide a good common one.
130	const parse = (section) =>
131	  Object.fromEntries(
132	    Object.entries(section)
133	      .filter(([id, v]) => kb.isKeybindingActionId(id) && expand(id, v) !== undefined)
134	      .map(([id, v]) => [id, expand(id, v)]),
135	  );
136	const commonParsed = parse(common);
137	const effective = { ...commonParsed, ...parse(linux) };
138	for (;;) {
139	  const withdrawn = kb
140	    .findKeybindingConflicts('linux', effective)
141	    .flatMap((c) => c.actionIds)
142	    .filter((id) => id in written);
143	  // Only generated keys are ever withdrawn. A conflict with none left in it
144	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
145	  // withdrawal brought back -- is Orca's to report.
146	  if (withdrawn.length === 0) break;
147	  for (const id of new Set(withdrawn)) {
148	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
149	    delete written[id];
150	    delete linux[id];
151	    if (id in commonParsed) effective[id] = commonParsed[id];
152	    else delete effective[id];
153	  }
154	}
155	
156	doc.version = 1;
157	doc.platforms = {
158	  ...platforms,
159	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
160	  linux,
161	  win32: isObject(platforms.win32) ? platforms.win32 : {},
162	};
163	writeJson(dest, doc);
164	// Every key this table claims, written or withdrawn, at its generated value;
165	// the UI's keep the value last written. Either way a later UI value reads as
166	// changed, the UI's, rather than as never owned and free to overwrite.
167	writeJson(sidecar, {
168	  linux: {
169	    ...owned,
170	    ...Object.fromEntries([...theirs].filter((id) => id in prev).map((id) => [id, prev[id]])),
171	    ...written,
172	  },
173	});

