  # opts?)`, keys joined with " + ". Two ways to render the dispatcher via
  # mkLuaInline:
  #   exec  - run a shell command; `hl.dsp.exec_cmd` is Hyprlang `exec`.
  #           (`hl.dsp.exec_raw`/Hyprlang `execr` runs a *program* without a
  #           shell. Neither is a dispatcher; those go through `hl.dsp.*` below.)
  #   dsp   - a structured dispatcher, e.g. hl.dsp.focus({ direction = "left" }),
  #           hl.dsp.window.close(), hl.dsp.window.move({ workspace = 1 }).
  # [=[ ... ]=] long brackets let shell commands keep their quotes and `]]`.
  exec = keys: cmd: {
    _args = [
      keys
      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
    ];
  };
  execOpts = keys: cmd: opts: {
    _args = [
      keys
      (mkLuaInline "hl.dsp.exec_cmd([=[${cmd}]=])")
      opts
    ];
  };
  dsp = keys: luaExpr: {
    _args = [
      keys
      (mkLuaInline luaExpr)
    ];
  };
  # Structured dispatcher with bind options (mouse drag/resize need
  # { mouse = true }).
  dspOpts = keys: luaExpr: opts: {
    _args = [
      keys
      (mkLuaInline luaExpr)
      opts
    ];
  };

  wsKeys = [
    "1"
    "2"
    "3"

    # exec-once equivalents. The module already emits a hyprland.start hook for
    # the systemd/D-Bus activation env, so we only add our own programs. The
    # xrdb -merge ahead of mako/elephant/everything-else is load-bearing: the X
    # server's resource database only exists across the lifetime of its
    # Xwayland instance, so anything `xrdb`-loaded before Hyprland starts pushes
    # values into a DB the compositor's Xwayland never reads. Loading it from
    # hyprland.start makes it the first thing to touch X for this session.
    on = [
      {
        _args = [
          "hyprland.start"
          (mkLuaInline ''
            function()
              hl.exec_cmd("${pkgs.xorg.xrdb}/bin/xrdb -merge ${config.home.homeDirectory}/.Xresources")
              hl.exec_cmd("mako")
              hl.exec_cmd("hypr-fullscreen-inhibit")
              hl.exec_cmd("elephant")
            end'')
        ];
      }

      # Pin Vesktop to workspace 8. Vesktop is the user's Discord client and
      # should live on ws8 regardless of where it was launched from. WM_CLASS is
      # "Vesktop" (capital V) -- from the StartupWMClass in
      # /nix/store/.../share/applications/vesktop.desktop. Static windowrulev2
      # would also work; using a window.open handler keeps the per-window
      # behaviour colocated with the rest of this file's hooks.
      {
        _args = [
          "window.open"
          (mkLuaInline ''
            function(w)
